using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using System.IO;using System.Linq;using System.Text;
[InitializeOnLoad] public static class GrandpaTemporary{
const string D="Library/GrandpaWork/";static GrandpaTemporary(){EditorApplication.delayCall+=Run;}
static void Run(){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().name!="Park"||File.Exists(D+"grip.txt"))return;
const string path="Assets/_Project/Prefabs/Characters/Park/GrandpaWithCane.prefab";var root=PrefabUtility.LoadPrefabContents(path);var cane=root.transform.Find("Деревянная трость");var shaft=cane.Find("Стержень");var a=new Vector3(-.15f,.595f,.06f);var b=new Vector3(-.34f,0,.49f);shaft.localPosition=(a+b)*.5f;shaft.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);shaft.localScale=new Vector3(.034f,(b-a).magnitude*.5f,.034f);cane.Find("Рукоятка").localPosition=a;PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);
var bench=Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(t=>t.name=="Bench_B"&&t.parent.name=="Скамейка и урна 2");Render(bench.position+bench.rotation*new Vector3(2,1.7f,4),bench.position+Vector3.up*.65f,D+"grip.png");File.WriteAllText(D+"grip.txt","OK");}
static void Rod(Transform parent,string name,Vector3 a,Vector3 b,float radius,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=(a+b)*.5f;g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);g.transform.localScale=new Vector3(radius*2,(b-a).magnitude*.5f,radius*2);g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());}
static string Path(Transform t){return t.parent?Path(t.parent)+"/"+t.name:t.name;}
public static void Render(Vector3 pos,Vector3 target,string path){var cg=new GameObject("Preview");var c=cg.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.fieldOfView=40;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.gray;var lg=new GameObject("Preview light");var l=lg.AddComponent<Light>();l.type=LightType.Directional;l.intensity=2;lg.transform.rotation=Quaternion.Euler(35,180,0);var rt=new RenderTexture(1200,1000,24);c.targetTexture=rt;c.Render();c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1200,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,1000),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());RenderTexture.active=prev;c.targetTexture=null;Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);Object.DestroyImmediate(cg);Object.DestroyImmediate(lg);}
}
